# DocType Event: Before Validate
user = frappe.session.user
roles = [row.role for row in frappe.get_doc("User", user).roles] if user != "Administrator" else ["System Manager"]
if not any(role in ("System Manager", "HR Manager", "HR User") for role in roles):
    frappe.throw("Only HR can change attendance incidents.", frappe.PermissionError)
if doc.incident_date and frappe.utils.getdate(doc.incident_date) > frappe.utils.getdate(frappe.utils.nowdate()):
    frappe.throw("The incident date cannot be in the future.")
if doc.employee:
    emp = frappe.get_doc("Employee", doc.employee)
    emp.check_permission("read")
    if doc.docstatus == 0:
        doc.employee_name = emp.employee_name
        doc.designation = emp.designation
        doc.job_description = emp.custom_fiche_de_poste
        doc.department = emp.department
        doc.company = emp.company
        doc.manager = emp.reports_to
for field in ("scheduled_start", "scheduled_end", "actual_arrival", "actual_departure"):
    if doc.get(field) and doc.incident_date:
        delta = (frappe.utils.get_datetime(doc.get(field)).date() - frappe.utils.getdate(doc.incident_date)).days
        if delta not in (-1, 0, 1):
            frappe.throw("Attendance times must belong to the incident shift.")
if doc.scheduled_start and doc.scheduled_end and frappe.utils.get_datetime(doc.scheduled_end) <= frappe.utils.get_datetime(doc.scheduled_start):
    frappe.throw("The scheduled end must follow the scheduled start.")
if doc.actual_arrival and doc.actual_departure and frappe.utils.get_datetime(doc.actual_departure) < frappe.utils.get_datetime(doc.actual_arrival):
    frappe.throw("Departure cannot precede arrival.")
doc.late_minutes = round(max(0, frappe.utils.time_diff_in_seconds(doc.actual_arrival, doc.scheduled_start) / 60), 2) if doc.actual_arrival and doc.scheduled_start else 0
doc.early_minutes = round(max(0, frappe.utils.time_diff_in_seconds(doc.scheduled_end, doc.actual_departure) / 60), 2) if doc.actual_departure and doc.scheduled_end else 0
if doc.late_minutes:
    a = frappe.utils.get_datetime(doc.scheduled_start)
    b = frappe.utils.get_datetime(doc.actual_arrival)
    doc.late_period = (str(a)[11:16] if a.date() == b.date() else str(a)[8:10] + "/" + str(a)[5:7] + " " + str(a)[11:16]) + " – " + (str(b)[11:16] if a.date() == b.date() else str(b)[8:10] + "/" + str(b)[5:7] + " " + str(b)[11:16])
else:
    doc.late_period = ""
if frappe.utils.flt(doc.absence_minutes) < 0:
    frappe.throw("Absence duration cannot be negative.")
if doc.incident_type == "Other" and not doc.other_incident:
    frappe.throw("Describe the other incident type.")
if doc.action_taken == "Other Action" and not doc.other_action:
    frappe.throw("Describe the other action.")
if doc.source_snapshot:
    snapshot = json.loads(doc.source_snapshot)
    if snapshot.get("employee") != doc.employee or frappe.utils.getdate(snapshot.get("incident_date")) != frappe.utils.getdate(doc.incident_date):
        frappe.throw("The employee or date changed. Prefill again.")

# DocType Event: Before Submit
user = frappe.session.user
roles = [row.role for row in frappe.get_doc("User", user).roles] if user != "Administrator" else ["System Manager"]
if not any(role in ("System Manager", "HR Manager", "HR User") for role in roles):
    frappe.throw("Only HR can validate attendance incidents.", frappe.PermissionError)
if not (doc.incident_type and doc.manager_observations and doc.action_taken):
    frappe.throw("Complete the incident, observations and action.")
if doc.incident_type == "Late Arrival" and (not doc.scheduled_start or not doc.actual_arrival or frappe.utils.flt(doc.late_minutes) <= 0):
    frappe.throw("Late arrival requires an actual arrival later than the scheduled time.")
if doc.incident_type == "Early Departure" and (not doc.scheduled_end or not doc.actual_departure or frappe.utils.flt(doc.early_minutes) <= 0):
    frappe.throw("Early departure requires an actual departure earlier than the scheduled time.")
if doc.incident_type in ("Justified Absence", "Unjustified Absence") and frappe.utils.flt(doc.absence_minutes) <= 0:
    frappe.throw("Enter the confirmed absence duration in minutes.")
doc.validated_by = user
doc.validated_on = frappe.utils.now_datetime()
doc.review_status = "Validated"
